    @GameTest(template="building_test_empty",timeoutTicks=30)
    public static void delayedWelcomeDisplayRenewsOnlyItsOwnNamingSession(GameTestHelper h)throws Exception{
        var p=AdventureGameTests.player(h);
        var act=JourneyNetwork.class.getDeclaredMethod("act",net.minecraft.server.level.ServerPlayer.class,JourneyNetwork.Action.class);
        act.setAccessible(true);
        act.invoke(null,p,new JourneyNetwork.Action(0,"welcome",""));
        var field=JourneyNetwork.class.getDeclaredField("sessions");field.setAccessible(true);
        @SuppressWarnings("unchecked") var sessions=(Map<UUID,Object>)field.get(null);
        var first=sessions.get(p.getUUID());var type=first.getClass();
        var tokenMethod=type.getDeclaredMethod("token");tokenMethod.setAccessible(true);
        long token=(Long)tokenMethod.invoke(first);
        act.invoke(null,p,new JourneyNetwork.Action(0,"welcome",""));
        h.assertTrue((Long)tokenMethod.invoke(sessions.get(p.getUUID()))==token,"duplicate MCA welcome preserves open form token");
        var constructor=type.getDeclaredConstructor(String.class,long.class,long.class);constructor.setAccessible(true);
        sessions.put(p.getUUID(),constructor.newInstance("profile",token,-1L));
        act.invoke(null,p,new JourneyNetwork.Action(token+1,"welcome_seen",""));
        var untilMethod=type.getDeclaredMethod("until");untilMethod.setAccessible(true);
        h.assertTrue((Long)untilMethod.invoke(sessions.get(p.getUUID()))==-1,"wrong token cannot renew profile");
        act.invoke(null,p,new JourneyNetwork.Action(token,"welcome_seen",""));
        h.assertTrue((Long)untilMethod.invoke(sessions.get(p.getUUID()))>=p.server.overworld().getGameTime()+2399,"display acknowledgement renews expired loading token");
        sessions.put(p.getUUID(),constructor.newInstance("profile",token,-1L));
        act.invoke(null,p,new JourneyNetwork.Action(token+1,"name","错误会话"));
        h.assertTrue(!JourneyData.get(p.server).player(p.getUUID()).getBoolean("Named"),"wrong form cannot rename player");
        act.invoke(null,p,new JourneyNetwork.Action(token,"name","  §  "));
        h.assertTrue(!JourneyData.get(p.server).player(p.getUUID()).getBoolean("Named"),"invalid name preserves unnamed state");
        act.invoke(null,p,new JourneyNetwork.Action(token,"name","星旅者"));
        h.assertTrue(JourneyData.get(p.server).player(p.getUUID()).getBoolean("Named"),"name can be submitted after long loading");
        h.assertTrue((Long)tokenMethod.invoke(sessions.get(p.getUUID()))==token,"success acknowledges original form instead of reopening another profile");
        h.succeed();
    }
    @GameTest(template="building_test_empty",timeoutTicks=50) public static void allActualPotionIngredientsAndCommissionTargetsExist(GameTestHelper h){for(var e:Elixir.values())for(String id:e.ingredients)h.assertTrue(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(id))!=null&&net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(id))!=Items.AIR,"Ingredient exists "+id);h.assertTrue(CommissionCatalog.all().size()==10,"Ten actual reloadable offers");for(var o:CommissionCatalog.all())if(o.kind().equals("kill"))h.assertTrue(net.minecraftforge.registries.ForgeRegistries.ENTITY_TYPES.containsKey(ResourceLocation.parse(o.target())),"Target exists "+o.target());h.succeed();}
    private static AlchemyEntity cauldron(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlock(pos,Blocks.AIR.defaultBlockState(),3);h.getLevel().setBlock(pos,AlchemyContent.CAULDRON.defaultBlockState(),3);return (AlchemyEntity)h.getLevel().getBlockEntity(pos);}
    private static void finishCook(GameTestHelper h,AlchemyEntity be){for(int i=0;i<AlchemyEntity.COOK_TICKS;i++){be.temperature=450;AlchemyEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);}}
    private static void fill(AlchemyEntity be,Elixir recipe){for(int i=0;i<3;i++)be.inventory.setItem(i,new ItemStack(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(recipe.ingredients.get(i))),2));be.inventory.setItem(5,new ItemStack(Items.GLASS_BOTTLE,2));be.fire=2;be.hasIgnited=true;be.temperature=400;be.water=3;be.burn=1600;}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void alchemyConsumesExactInputsAndPausesAtBlockedOutput(GameTestHelper h){var be=cauldron(h);fill(be,Elixir.SPRING);for(int i=0;i<Elixir.SPRING.ticks;i++){be.temperature=450;AlchemyEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);}h.assertTrue(be.ready.isEmpty()&&be.vortex_sync==100&&be.inventory.getItem(0).getCount()==2,"hot fusion waits for physical sealing without consuming herbs");h.assertTrue(be.seal(null)&&be.ready.isEmpty(),"lid starts post-cooking");finishCook(h,be);h.assertTrue(be.readyQuality==2&&be.ready.equals("spring")&&be.water==2&&be.inventory.getItem(0).getCount()==1&&be.inventory.getItem(5).getCount()==2,"golden-frame seal consumes exactly one batch, bottle only on collection");h.assertTrue(!be.seal(null),"cannot seal twice");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void cauldronSaveAndSurvivalDropPreserveOneInventory(GameTestHelper h){var be=cauldron(h);fill(be,Elixir.BLOOM);for(int i=0;i<80;i++)AlchemyEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);var saved=be.saveWithoutMetadata();var restored=new AlchemyEntity(be.getBlockPos(),be.getBlockState());restored.load(saved);h.assertTrue(restored.progress==80&&restored.burn==be.burn&&restored.inventory.getItem(0).getCount()==2,"restart preserves exact progress and inputs");var drops=Block.getDrops(be.getBlockState(),h.getLevel(),be.getBlockPos(),be);h.assertTrue(drops.size()==1&&drops.get(0).is(AlchemyContent.CAULDRON.asItem()),"one packed cauldron drop");var packed=drops.get(0).getTagElement("BlockEntityTag");h.assertTrue(packed!=null&&packed.getInt("Progress")==80&&!packed.getList("Items",10).isEmpty(),"packed loot keeps progress and inventory");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=30) public static void preparationStorageIsPrivateAndSipCannotOverwriteAnOpenMenu(GameTestHelper h){var p=AdventureGameTests.player(h);var q=AdventureGameTests.player(h);var st=new Preparation.Storage(p);st.setItem(27,new ItemStack(AlchemyContent.POTIONS.get(Elixir.BLOOM),2));p.containerMenu=new PreparationMenu(11,p.getInventory(),st,1);p.setHealth(2);Preparation.sip(p);h.assertTrue(new Preparation.Storage(p).getItem(27).getCount()==2&&p.getHealth()==2,"open menu packet cannot consume via stale copy");p.containerMenu=p.inventoryMenu;Preparation.sip(p);h.assertTrue(new Preparation.Storage(p).getItem(27).getCount()==1&&p.getHealth()==10,"one actual carried potion consumed");Preparation.sip(p);h.assertTrue(new Preparation.Storage(p).getItem(27).getCount()==1,"shared cooldown prevents duplicate use");h.assertTrue(new Preparation.Storage(q).getItem(27).isEmpty(),"another player's storage is empty");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=30) public static void commissioningCountsKeepLegacyProgressAcrossMigration(GameTestHelper h){var old=new CompoundTag();old.putInt("NativeBounties",7);var profile=AdventureSavedData.readProfile(old);profile.recordCommission();h.assertTrue(profile.commissions()==8&&profile.reputation()==5,"old seven paper jobs plus one electronic job");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void realBoardAcceptProgressClaimAndDuplicateAreAuthoritative(GameTestHelper h)throws Exception{
        var world=h.getLevel().getServer().overworld();var store=world.getDataStorage();var old=com.tnc.tnc.world.SkyIslandSavedData.get(world);var load=old.getClass().getDeclaredMethod("load",CompoundTag.class);load.setAccessible(true);var pos=h.absolutePos(new BlockPos(4,2,4));var t=old.save(new CompoundTag());var origin=pos.subtract(com.tnc.tnc.tavern.TavernUpgrade.BOARD);t.putString("Phase","COMPLETE");t.putBoolean("LayoutReady",true);t.putInt("OriginX",origin.getX());t.putInt("OriginY",origin.getY());t.putInt("OriginZ",origin.getZ());store.set("tnc_sky_island_v5",(net.minecraft.world.level.saveddata.SavedData)load.invoke(null,t));
        try{var p=AdventureGameTests.player(h);p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);AdventureService.register(p);world.setBlock(pos,AlchemyContent.BOARD.defaultBlockState(),3);CommissionService.openAt(p,pos);CommissionService.act(p,"accept","tnc:road_watch");CommissionService.act(p,"accept","tnc:road_watch");var record=CommissionService.ledger(p).getCompound("tnc:road_watch");h.assertTrue(record.getBoolean("Active")&&record.getInt("Progress")==0,"board accepts exactly one job");CommissionService.progress(p,"kill","minecraft:spider");h.assertTrue(record.getInt("Progress")==0,"wrong target not counted");for(int i=0;i<10;i++)CommissionService.progress(p,"kill","minecraft:zombie");h.assertTrue(record.getInt("Progress")==6,"goal capped");CommissionService.act(p,"claim","tnc:road_watch");CommissionService.act(p,"claim","tnc:road_watch");h.assertTrue(AdventureService.profile(p).coins()==75&&AdventureService.profile(p).commissions()==1&&AdventureService.profile(p).hasMilestone("first_contract")&&AdventureService.profile(p).hasMilestone("bounties_1"),"one reward and existing FTB advancements");CommissionService.act(p,"accept","tnc:road_watch");h.assertTrue(!record.getBoolean("Active"),"real-time repeat cooldown");var removed=new CompoundTag();removed.putBoolean("Active",true);removed.putInt("Goal",3);CommissionService.ledger(p).put("removed:old_offer",removed);h.assertTrue(CommissionService.snapshot(p).getList("Cards",10).stream().map(n->(CompoundTag)n).anyMatch(n->n.getString("Id").equals("removed:old_offer")&&n.getBoolean("Unavailable")),"removed data-pack offer stays visible");CommissionService.act(p,"abandon","removed:old_offer");h.assertTrue(!removed.getBoolean("Active"),"removed offer can be abandoned without catalog entry");}finally{store.set("tnc_sky_island_v5",old);}h.succeed();
    }
